import { getLogger } from '~/lib/log';
import { events } from '~/lib/events';
import '~/lib/state/layout';

export default function header(options = {}) {
  const { headerStyle = 'solid' } = options;
  const log = getLogger(this.$id('header'));

  return {
    /**
     * State
     */
    mobileMenuOpen: false,
    headerStyle,

    /**
     * Lifecycle Methods
     */
    init() {
      log.debug('Header component initialized');
    },

    destroy() {
      log.debug('Header component destroyed');
    },

    /**
     * Instance Methods
     */
    toggleMobileMenu() {
      this.mobileMenuOpen = !this.mobileMenuOpen;

      // Update layout properties when opening mobile menu
      if (this.mobileMenuOpen) {
        // Prevent body scroll when mobile menu is open
        document.body.style.overflow = 'hidden';
        // Dispatch event for other components
        this.$dispatch(events.header.mobileMenuOpened);
      } else {
        // Restore body scroll when mobile menu is closed
        document.body.style.overflow = '';
        // Dispatch event for other components
        this.$dispatch(events.header.mobileMenuClosed);
      }

      log.debug('toggleMobileMenu', { open: this.mobileMenuOpen });
    },

    closeMobileMenu() {
      if (this.mobileMenuOpen) {
        this.mobileMenuOpen = false;
        document.body.style.overflow = '';
        this.$dispatch(events.header.mobileMenuClosed);
        log.debug('closeMobileMenu');
      }
    },

    closeAll() {
      this.closeMobileMenu();
      // Dispatch event to close other header components
      this.$dispatch(events.header.closeAll);
      log.debug('closeAll');
    },
    /**
     * Computed Properties
     */
    get headerClasses() {
      return {
        scrolled: this.isScrolled,
      };
    },

    /**
     * Alpine.js Directives
     */
    directives: {
      self: {
        ':class'() {
          return this.headerClasses;
        },
        '@keydown.escape.window'() {
          this.closeAll();
        },
        '@click.outside'() {
          this.closeAll();
        },
        '@resize.window'() {
          if (this.isSticky) {
            this.updateLayoutProperties();
          }
        },
        '@scroll.window.passive'() {
          if (this.isSticky && this.handleScroll) {
            this.handleScroll();
          }
        },
      },
      mobileMenuToggle: {
        '@click'() {
          this.toggleMobileMenu();
        },
        ':aria-expanded'() {
          return this.mobileMenuOpen;
        },
      },
      mobileMenu: {
        ':class'() {
          return { hidden: !this.mobileMenuOpen };
        },
        ':aria-hidden'() {
          return !this.mobileMenuOpen;
        },
      },
      searchToggle: {
        '@click'() {
          this.$dispatch(events.search.toggle);
        },
      },
    },
  };
}
